CalorSource:
§M{m001:Leg2:overflow=unchecked}
  §NS{ns001:Serilog.Events:file}
    // A property associated with a LogEvent.
    §CL{c002:LogEventProperty:pub}
      // The name of the property.
      §PROP{p006:Name:str:pub:get}
      // The value of the property.
      §PROP{p007:Value:LogEventPropertyValue:pub:get}

      §CTOR{ctor003:pub} (str:name, LogEventPropertyValue:value)
        §C{Guard.AgainstNull} value
        §C{EnsureValidName} name
        §ASSIGN Name name
        §ASSIGN Value value

      §CTOR{ctor004:int} (EventProperty:property)
        §IF{if005} (equals property EventProperty.None)
          §TH §NEW{ArgumentNullException} §A (nameof property) §/NEW
        §ASSIGN Name property.Name
        §ASSIGN Value property.Value

      // Test name to determine if it is a valid property name.
      // @param name — The name to check.
      // @returns true if the name is valid; otherwise, false.
      §MT{m008:IsValidName:pub:stat}
        §I{?str:name}[@NotNullWhen(true)]
        §O{bool}
        §R (! (isblank name))

      // @throws ArgumentNullException — When name is null
      // @throws ArgumentException — When name is empty or only contains whitespace
      §MT{m009:EnsureValidName:int:stat}[@MethodImpl(MethodImplOptions.AggressiveInlining)] (str:name)
        §E{throw,alloc}
        §C{Guard.AgainstNull} name
        §B{_preIsValidName011} §C{IsValidName} name
        §IF{if010} (! _preIsValidName011)
          §TH §NEW{ArgumentException} §A "Property ${(nameof name)} must not be empty or whitespace." §A (nameof name) §/NEW
